5593			info.total--
5594			if info.total == 0 {
5595				if _, ok = fs.psim.Delete(bsubj); ok {
5596					fs.tsl -= len(subj)
5597					return 0
5598				}
5599			}
5600			return info.total
5601		}
5602		return 0
5603	}
